<?php
require_once 'includes/config.php';require_admin();$sid=(int)($_GET['student_id']??$_POST['student_id']??0);$msg='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['record_payment'])){try{verify_csrf();$sid=(int)($_POST['student_id']??0);$fid=(int)($_POST['fee_id']??0);$amount=filter_var($_POST['amount']??null,FILTER_VALIDATE_FLOAT);$date=(string)($_POST['payment_date']??date('Y-m-d'));$method=trim((string)($_POST['payment_method']??'Cash'));if(!$sid||!$fid||$amount===false||$amount<=0||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))throw new RuntimeException('Enter a valid student, fee, amount and payment date.');$dbh->beginTransaction();$q=$dbh->prepare('SELECT f.id,f.student_id,f.amount_due,COALESCE(SUM(p.amount),0) paid FROM student_term_fees f LEFT JOIN student_fee_payments p ON p.fee_id=f.id WHERE f.id=:f GROUP BY f.id,f.student_id,f.amount_due FOR UPDATE');$q->execute([':f'=>$fid]);$fee=$q->fetch();if(!$fee||(int)$fee['student_id']!==$sid)throw new RuntimeException('The selected fee record does not belong to this student.');$balance=max(0,(float)$fee['amount_due']-(float)$fee['paid']);if($amount>$balance+0.00001)throw new RuntimeException('Payment exceeds the outstanding balance.');$receipt='SRMS-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(4)));$ins=$dbh->prepare('INSERT INTO student_fee_payments(fee_id,amount,payment_date,payment_method,receipt_number,notes,recorded_by) VALUES(:f,:a,:d,:m,:r,:n,:u)');$ins->execute([':f'=>$fid,':a'=>$amount,':d'=>$date,':m'=>$method,':r'=>$receipt,':n'=>trim((string)($_POST['notes']??'')),':u'=>(int)($_SESSION['admin_id']??0)]);$paymentId=(int)$dbh->lastInsertId();$tx='TXN-'.strtoupper(bin2hex(random_bytes(12)));$audit=$dbh->prepare('INSERT INTO fee_transaction_audit(transaction_id,fee_id,student_id,amount,payment_timestamp,receipt_reference,payment_method,recorded_by) VALUES(:tx,:f,:s,:a,NOW(),:r,:m,:u)');$audit->execute([':tx'=>$tx,':f'=>$fid,':s'=>$sid,':a'=>$amount,':r'=>$receipt,':m'=>$method,':u'=>(int)($_SESSION['admin_id']??0)]);$queue=$dbh->prepare("INSERT INTO fee_receipt_queue(transaction_id,status) VALUES(:tx,'queued')");$queue->execute([':tx'=>$tx]);$dbh->commit();audit_log($dbh,'FEE_PAYMENT_RECORDED',$tx.' / '.$receipt.' / amount '.$amount);$msg='Payment saved. Receipt reference: '.$receipt;$receiptUrl='fee-payment-receipt.php?id='.$paymentId;}catch(Throwable $e){if($dbh->inTransaction())$dbh->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'Payment was not saved. Confirm Phase 11 migration is installed and review the application log.';error_log('SRMS payment: '.$e->getMessage());}}
$student=null;$fees=[];$payments=[];if($sid){$q=$dbh->prepare('SELECT s.StudentId,s.StudentName,s.RollId,s.ClassId,c.ClassName,c.Section FROM tblstudents s LEFT JOIN tblclasses c ON c.id=s.ClassId WHERE s.StudentId=:s');$q->execute([':s'=>$sid]);$student=$q->fetch();if($student){$q=$dbh->prepare('SELECT f.*,COALESCE(SUM(p.amount),0) paid FROM student_term_fees f LEFT JOIN student_fee_payments p ON p.fee_id=f.id WHERE f.student_id=:s GROUP BY f.id ORDER BY f.academic_year DESC,f.term');$q->execute([':s'=>$sid]);$fees=$q->fetchAll();$q=$dbh->prepare('SELECT p.*,f.academic_year,f.term FROM student_fee_payments p JOIN student_term_fees f ON f.id=p.fee_id WHERE f.student_id=:s ORDER BY p.payment_date DESC,p.id DESC LIMIT 100');$q->execute([':s'=>$sid]);$payments=$q->fetchAll();}}
$students=$dbh->query('SELECT StudentId,StudentName,RollId FROM tblstudents ORDER BY StudentName')->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Student Financial Workspace</title><link rel="stylesheet" href="css/bootstrap.min.css"><link rel="stylesheet" href="css/main.css"><link rel="stylesheet" href="css/srms-modernization.css"><link rel="stylesheet" href="css/srms-responsive.css"></head><body class="top-navbar-fixed"><div class="main-wrapper"><?php include 'includes/topbar.php';?><div class="content-wrapper"><div class="content-container"><?php include 'includes/leftbar.php';?><main class="main-page"><div class="container srms-page"><p><a href="manage-fees.php">← Fees Management</a> | <a href="fee-reports.php">Financial Reports</a></p><h2>Student Financial Workspace</h2><p class="text-muted">All fee amounts are shown in Malawi Kwacha (MWK).</p><?php if($msg):?><div class="alert alert-success"><?=e($msg)?> <?php if(!empty($receiptUrl)):?><a class="btn btn-default" target="_blank" href="<?=e($receiptUrl)?>">Open printable receipt</a><?php endif;?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="get" class="form-inline"><label>Select student</label> <select name="student_id" class="form-control" required><option value="">Choose student</option><?php foreach($students as $s):?><option value="<?=$s['StudentId']?>" <?=$sid===(int)$s['StudentId']?'selected':''?>><?=e($s['StudentName'].' — '.$s['RollId'])?></option><?php endforeach;?></select> <button class="btn btn-primary">Load live ledger</button></form><?php if($sid&&!$student):?><p class="alert alert-warning m-t-20">Student not found.</p><?php endif;?><?php if($student):?><h3><?=e($student['StudentName'])?> <small><?=e($student['RollId'].' · '.$student['ClassName'].' '.$student['Section'])?></small></h3><div class="panel panel-default"><div class="panel-heading">Record a payment</div><div class="panel-body"><form method="post" class="row"><?=csrf_field()?><input type="hidden" name="record_payment" value="1"><input type="hidden" name="student_id" value="<?=$sid?>"><div class="col-md-4 form-group"><label>Term fee ledger</label><select name="fee_id" class="form-control" required><option value="">Choose outstanding fee</option><?php foreach($fees as $f):$bal=max(0,(float)$f['amount_due']-(float)$f['paid']);if($bal<=0)continue;?><option value="<?=$f['id']?>"><?=e($f['academic_year'].' / '.$f['term'].' — balance '.number_format($bal,2))?></option><?php endforeach;?></select></div><div class="col-md-2 form-group"><label>Amount paid</label><input type="number" name="amount" min="0.01" step="0.01" class="form-control" required></div><div class="col-md-2 form-group"><label>Date</label><input type="date" name="payment_date" value="<?=date('Y-m-d')?>" class="form-control" required></div><div class="col-md-2 form-group"><label>Method</label><select name="payment_method" class="form-control"><option>Cash</option><option>Bank transfer</option><option>Mobile money</option><option>Cheque</option><option>Other</option></select></div><div class="col-md-2 form-group"><label>Notes</label><input name="notes" class="form-control" maxlength="255"></div><div class="col-md-12"><button class="btn btn-success">Save payment and queue receipt</button></div></form></div></div><h3>Live fee ledger</h3><div class="table-responsive"><table class="table table-bordered"><thead><tr><th>Year / Term</th><th>Total Due (MWK)</th><th>Total Paid (MWK)</th><th>Balance (MWK)</th><th>Status</th></tr></thead><tbody><?php foreach($fees as $f):$b=max(0,(float)$f['amount_due']-(float)$f['paid']);$st=$b<=0?'Fully Paid':((float)$f['paid']>0?'Partially Paid':'Unpaid');?><tr><td><?=e($f['academic_year'].' / '.$f['term'])?></td><td><?=number_format($f['amount_due'],2)?></td><td><?=number_format($f['paid'],2)?></td><td><?=number_format($b,2)?></td><td><?=e($st)?></td></tr><?php endforeach;?></tbody></table></div><h3>Payment transaction history</h3><div class="table-responsive"><table class="table table-striped table-bordered"><thead><tr><th>Date</th><th>Year / Term</th><th>Amount</th><th>Method</th><th>Receipt</th><th>Document</th></tr></thead><tbody><?php foreach($payments as $p):?><tr><td><?=e($p['payment_date'])?></td><td><?=e($p['academic_year'].' / '.$p['term'])?></td><td><?=number_format($p['amount'],2)?></td><td><?=e($p['payment_method'])?></td><td><?=e($p['receipt_number'])?></td><td><a target="_blank" href="fee-payment-receipt.php?id=<?=$p['id']?>">Print / PDF</a></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div></main></div></div></div></div></body></html>
